import {mountMarketing} from './marketing-interactions.js';
import {landing,stepPanel} from './landing.js';
import {shell,filteredTable,providerCards} from './app.js';
import {docs,tokenPage} from './docs.js';
import {icon,esc,avatar,money,download} from './ui.js';
import {seedJobs,providers,samplePackage,integrationCode} from './data.js';
import {site} from './config.js';
import {apiEnabled,ensureSession,sessionToken,signedInWallet,signOut,loadJobs,loadProviders,sampleChunkFiles,withSampleNormalize,createRecovery,authorizeRecovery,acceptJob,rejectJob,cancelJob,retryJob,disputeJob,settleJob,loadOutput} from './api.js';
const KEY='relayworks-prototype-v02';
function cleanJobs(jobs){return (jobs||[]).map(j=>({...j,events:Array.isArray(j.events)?j.events.map(e=>({...e,label:typeof e.label==='string'?e.label.replace(/\bdemo\b/gi,'').replace(/\s{2,}/g,' ').trim():e.label,detail:typeof e.detail==='string'?e.detail.replace(/\bdemo\b/gi,'').replace(/\s+·\s+(no real transfer|simulated)/gi,'').replace(/\s{2,}/g,' ').trim():e.detail})):j.events}))}
let live=apiEnabled();
const defaults=()=>({jobs:live?[]:structuredClone(seedJobs),workspace:'My workspace',defaultBudget:10,savedProviders:[],jobFilter:'All jobs',jobSearch:'',providerSearch:'',providerSort:'recommended',selectedProvider:'patch',live,modeLabel:'Live',needsAuth:live&&!sessionToken(),wallet:signedInWallet(),cluster:site.cluster||'devnet'});
let state=defaults();
let savedLocalJobs=null;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');const jobsOk=saved&&Array.isArray(saved.jobs)&&saved.jobs.every(j=>typeof j.id==='string'&&typeof j.title==='string'&&Number.isFinite(j.total)&&j.total>0&&Number.isFinite(j.completed)&&Number.isFinite(j.budget)&&Array.isArray(j.events));if(jobsOk){savedLocalJobs=cleanJobs(saved.jobs);state={...defaults(),...saved,jobs:live?[]:savedLocalJobs,live,modeLabel:'Live',needsAuth:live&&!sessionToken(),wallet:signedInWallet(),cluster:site.cluster||'devnet'};state.savedProviders=Array.isArray(saved.savedProviders)?saved.savedProviders:[];}else if(saved&&typeof saved==='object'){state={...state,workspace:saved.workspace||state.workspace,defaultBudget:saved.defaultBudget||state.defaultBudget,savedProviders:Array.isArray(saved.savedProviders)?saved.savedProviders:[],selectedProvider:saved.selectedProvider||state.selectedProvider};}}catch{}
let lastRoute='',toastTimer,modal=null,lastFocus=null,currentCode='python',observer,frame=0;
let relayScene=null,journey=null,heroScrollCleanup=null,sceneVersion=0,marketingCleanup=null;
const copyCa=()=>site.token.contract?copyText(site.token.contract).then(()=>toast('Contract address copied. Double-check it on '+site.xHandle+'.')):toast('No contract address yet. It drops here and on '+site.xHandle+' at launch.');
const recoveryTimers=new Map();
const root=document.getElementById('root');
function persist(){try{const payload=live?{workspace:state.workspace,defaultBudget:state.defaultBudget,savedProviders:state.savedProviders,jobFilter:state.jobFilter,jobSearch:state.jobSearch,providerSearch:state.providerSearch,providerSort:state.providerSort,selectedProvider:state.selectedProvider}:state;localStorage.setItem(KEY,JSON.stringify(payload))}catch{toast('Browser storage unavailable. Export your workspace to keep it.')}}
async function refreshLive(){if(!live)return;if(!sessionToken()){state.needsAuth=true;state.wallet='';state.jobs=[];if(location.hash.startsWith('#/app')&&!modal)rerender();return}try{state.needsAuth=false;state.wallet=signedInWallet();const [jobs,remote]=await Promise.all([loadJobs(),loadProviders()]);state.jobs=jobs;state.wallet=signedInWallet();for(const item of remote){const local=providers.find(p=>p.id===item.id);if(!local)continue;local.price=item.quoteCents/100;local.asset=item.assetPubkey;local.executable=item.executable}}catch(err){if(err.message==='NO_WALLET'||/sign in/i.test(err.message)||/\(401\)/.test(err.message)){state.needsAuth=true;state.wallet='';state.jobs=[];if(location.hash.startsWith('#/app')&&!modal)rerender();return}toast(err.message||'The control API did not answer.')}if(location.hash.startsWith('#/app')&&modal?.kind!=='new')rerender()}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function route(){const sectionHash=location.hash&&!location.hash.startsWith('#/')?location.hash:null;const hash=sectionHash?'#/':location.hash||'#/';const parts=hash.slice(2).split('/').filter(Boolean);const routeKey=hash;disposeRelayScene();closeModal();if(frame)cancelAnimationFrame(frame);if(observer)observer.disconnect();if(parts[0]==='app'){try{root.innerHTML=shell(state,parts.slice(1))}catch(err){root.innerHTML=`<main class="noscript"><h1>Console hit a snag.</h1><p>${esc(err.message||'Could not draw this page.')}</p></main>`}document.title=`${parts[1]==='jobs'?'Broken jobs':parts[1]==='market'?'The crew':parts[1]==='receipts'?'Receipts':'Console'} · RelayWorks`;}else if(parts[0]==='docs'){root.innerHTML=docs(parts[1]);document.title='The blueprint · RelayWorks';}else if(parts[0]==='token'){root.innerHTML=tokenPage();document.title='$RELAY · RelayWorks';}else{root.innerHTML=landing();document.title='RelayWorks | Your AI agent quit at 70%. Patch finishes the job.';setupLanding();}if(lastRoute!==routeKey||!parts.length){window.scrollTo({top:0,behavior:'instant'});lastRoute=routeKey;}if(parts[0]==='app'&&parts[1]==='market'&&parts[2])openProvider(parts[2]);if(parts[0]==='app'&&live)refreshLive();if(sectionHash)requestAnimationFrame(()=>document.getElementById(sectionHash.slice(1))?.scrollIntoView({behavior:'instant'}));}
function rerender(){const scroll=window.scrollY;try{root.innerHTML=shell(state,(location.hash.slice(2).split('/').filter(Boolean)).slice(1))}catch(err){root.innerHTML=`<main class="noscript"><h1>Console hit a snag.</h1><p>${esc(err.message||'Could not draw this page.')}</p></main>`}window.scrollTo({top:scroll,behavior:'instant'})}
function disposeRelayScene(){sceneVersion++;heroScrollCleanup?.();heroScrollCleanup=null;relayScene?.dispose();relayScene=null;journey?.dispose();journey=null;marketingCleanup?.();marketingCleanup=null;}
function setupLanding(){
  currentCode='python';
  marketingCleanup?.();marketingCleanup=mountMarketing(document.querySelector('.fun'));
}
function selectStep(i,fromScene=false){
  document.querySelectorAll('.step-tab').forEach((b,n)=>{b.classList.toggle('selected',n===i);b.setAttribute('aria-selected',String(n===i))});
  document.querySelectorAll('.engine-step').forEach((b,n)=>{b.classList.toggle('selected',n===i);b.setAttribute('aria-pressed',String(n===i))});
  const panel=document.getElementById('step-panel');if(panel){panel.innerHTML=stepPanel(i);panel.setAttribute('aria-labelledby','step-tab-'+i)}
  if(!fromScene){if(relayScene)relayScene.setStage(i);else{updateRelayUi(i,false);updateRelayProgress(i===3?100:i===2?85:70)}}
}
function updateRelayUi(i,playing){
  const labels=['Checkpoint captured','Specialist matched','Recovering work','Checks passed'];
  const details=['70 preserved · 30 remaining','Patch selected · 6.40 USDC quote','Resuming only the unfinished units','100 units complete · checks passed'];
  const status=document.getElementById('hero-status');if(status){status.className='status '+(i===3?'green':i===2?'blue':'orange');status.innerHTML='<i></i>'+labels[i]}
  const remaining=document.getElementById('hero-remaining');if(remaining)remaining.textContent=details[i];
  const dock=document.getElementById('scene-dock-label');if(dock)dock.textContent=['Ready for the handoff.','A specialist, selected.','Picking up the progress.','Good work, continued.'][i];
  const pause=document.querySelector('[data-action="engine-pause"]');if(pause){pause.innerHTML=icon(playing?'pause':'play')+'<span>'+(playing?'Pause':'Play')+'</span>';pause.setAttribute('aria-label',playing?'Pause animation':'Play animation')}
}
function updateRelayProgress(n){const count=document.getElementById('hero-completed');if(count)count.textContent=String(n);const fill=document.getElementById('hero-progress-fill');if(fill){fill.style.width=n+'%';fill.style.background=n===100?'var(--green)':'var(--orange)'}}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable. You can select and copy the example.')}}
function heroDemo(){document.getElementById('product')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function openModal(title,subtitle,body,actions,eyebrow='RELAYWORKS / LIVE'){const host=document.getElementById('modal-root');let dialog=host.querySelector('.modal');if(!dialog){lastFocus=document.activeElement;document.body.classList.add('modal-open');host.innerHTML=`<div class="modal-overlay" data-action="overlay-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-top"><div><div class="eyebrow"></div><h2 id="modal-title"></h2><p></p></div><button class="icon-btn" type="button" aria-label="Close dialog" data-action="close-modal">${icon('close')}</button></div><div class="modal-body"></div><div class="modal-bottom"></div></section></div>`;dialog=host.querySelector('.modal');}else{host.querySelector('.modal-overlay')?.classList.add('modal-held');}dialog.querySelector('.eyebrow').textContent=eyebrow;dialog.querySelector('#modal-title').textContent=title;dialog.querySelector('.modal-top p').textContent=subtitle;const panel=dialog.querySelector('.modal-body');panel.innerHTML=body;panel.scrollTop=0;dialog.querySelector('.modal-bottom').innerHTML=actions;const focus=dialog.querySelector('[autofocus]');if(focus)focus.focus();else if(!dialog.contains(document.activeElement))dialog.querySelector('.modal-bottom .btn-dark, .icon-btn')?.focus();}
function closeModal(){if(document.getElementById('modal-root').innerHTML){document.getElementById('modal-root').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.isConnected&&lastFocus.focus()}modal=null;}
function newJob(){modal={kind:'new',step:1,package:null,text:'',title:'',budget:state.defaultBudget||10,error:''};renderJobModal()}
function renderJobModal(){const m=modal;let body='';if(m.step===1){body=`<div class="upload-area">${icon('upload')}<strong>Bring your recovery package</strong><p>JSON · maximum 1 MB · stays in your browser</p><span class="btn btn-outline btn-xs">Choose a file</span><input id="package-file" aria-label="Upload recovery package JSON" type="file" accept=".json,application/json"></div><button class="sample-link" data-action="use-sample">Use the 70-of-100 sample package ${icon('right')}</button>${state.live?'<label for="chunk-files">Chunk files · name each file chunk-001.json</label><input id="chunk-files" aria-label="Upload chunk files" type="file" accept=".json,.csv,application/json,text/csv" multiple>':''}<label for="package-json">Or paste package JSON</label><textarea id="package-json" rows="8" placeholder='{"version":"0.1","total_units":100,"completed_units":70,...}'>${esc(m.text)}</textarea><p class="form-help">Use sample or non-sensitive data. This frontend validates the package shape; it does not execute its contents.</p>`}else if(m.step===2){body=`<div class="package-summary"><div>Total units<strong>${m.package.total_units}</strong></div><div>Preserved<strong>${m.package.completed_units}</strong></div><div>Remaining<strong>${m.package.total_units-m.package.completed_units}</strong></div></div><div class="form-row"><label for="recovery-title">Recovery name</label><input autofocus id="recovery-title" maxlength="80" required value="${esc(m.title)}" placeholder="e.g. Customer dataset enrichment"></div><div class="form-grid"><div><label for="recovery-budget">Maximum budget · USDC</label><input id="recovery-budget" type="number" min="1" max="1000" step="0.01" value="${m.budget}"><p class="form-help">Quotes above this cap cannot be started.</p></div><div><label for="recovery-type">Task category</label><select id="recovery-type"><option>Structured data</option></select><p class="form-help">Structured JSON and CSV jobs.</p></div></div>`}else{body=`<p style="font-size:13px;line-height:1.8">Your recovery package is ready. Compare providers before the handoff.</p><div class="review-box"><div><span>Recovery</span><strong>${esc(m.title)}</strong></div><div><span>Task category</span><strong>Structured data</strong></div><div><span>Progress preserved</span><strong>${m.package.completed_units} / ${m.package.total_units} units</strong></div><div><span>Remaining work</span><strong>${m.package.total_units-m.package.completed_units} units</strong></div><div><span>Maximum budget</span><strong>${money(m.budget)} USDC</strong></div><div><span>Execution</span><strong>Pay after acceptance</strong></div></div><label class="check-label"><input id="demo-confirm" type="checkbox">${state.live?'I understand USDC moves only after I accept the output.':'I understand USDC moves only after I accept the output.'}</label>`}if(m.error)body+=`<p class="form-error" role="alert">${esc(m.error)}</p>`;body+=`<div class="step-dots" aria-label="Step ${m.step} of 3">${[1,2,3].map(n=>`<span class="${n<=m.step?'active':''}"></span>`).join('')}</div>`;const actions=`${m.step===1?'<span>01 / 03 · Import package</span>':'<button type="button" class="btn btn-outline" data-action="new-back">Back</button>'}<button type="button" class="btn btn-dark" data-action="new-next">${m.step===3?(state.live?'Create recovery':'Create recovery'):'Continue'} ${icon('right')}</button>`;openModal(m.step===1?'Upload the mess.':m.step===2?'Set the rules.':'Ready to call Patch.','Start a rescue from whatever your agent finished.',body,actions);modal=m;}
function parsePackage(text){if(text.length>1000000)throw Error('Keep your package under 1 MB.');let p;try{p=JSON.parse(text)}catch{throw Error('This isn’t valid JSON yet. Check the package and try again.')}if(!p||typeof p!=='object'||Array.isArray(p))throw Error('The package must be a JSON object.');if(!Number.isInteger(p.total_units)||p.total_units<1||p.total_units>1000000)throw Error('total_units must be a whole number between 1 and 1,000,000.');if(!Number.isInteger(p.completed_units)||p.completed_units<0||p.completed_units>=p.total_units)throw Error('completed_units must be a whole number below total_units, with work remaining.');if(!p.version||typeof p.version!=='string'||p.version.length>20)throw Error('Add a package version, such as "0.1".');return p}
function nextNew(){const m=modal;if(!m||m.kind!=='new')return;m.error='';if(m.step===1){m.text=document.getElementById('package-json').value;try{m.package=parsePackage(m.text);m.title=String(m.package.title||'Untitled recovery').slice(0,80);m.step=2}catch(e){m.error=e.message}}else if(m.step===2){m.title=document.getElementById('recovery-title').value.trim();m.budget=Number(document.getElementById('recovery-budget').value);if(!m.title)m.error='Give this recovery a name.';else if(!Number.isFinite(m.budget)||m.budget<1||m.budget>1000||Math.abs(m.budget*100-Math.round(m.budget*100))>.00001)m.error='Use a budget from 1 to 1,000 USDC, with at most two decimals.';else m.step=3}else{if(!document.getElementById('demo-confirm').checked){m.error='Confirm that payment waits until you accept the output.'}else if(state.live){const files=m.files||[];if(!files.length)m.error='Add a file for every chunk, or use the sample.';else{const pkg=m.usedSample?withSampleNormalize(m.package):m.package;const title=m.title;const budget=m.budget;closeModal();toast('Sending the package…');ensureSession().then(()=>createRecovery({title,budget,pkg,files})).then(job=>{location.hash='#/app/jobs/'+job.id;toast('Rescue created. Pick a fixer.');return refreshLive()}).catch(err=>{toast(err.message||'The package was rejected.')});return}}else{const id='RW-'+String(Math.max(24,...state.jobs.map(j=>Number(j.id.replace('RW-',''))||0))+1).padStart(3,'0');state.jobs.unshift({id,title:m.title,type:'Structured data',total:m.package.total_units,completed:m.package.completed_units,originalCompleted:m.package.completed_units,status:'Needs rescue',budget:m.budget,provider:null,price:0,package:m.package,created:'Just now',events:[{label:'Recovery package imported',detail:`${m.package.completed_units} units preserved · package v${m.package.version}`,kind:'upload'}]});persist();closeModal();location.hash='#/app/jobs/'+id;toast('Rescue created. Pick a fixer.');return}}renderJobModal()}
function openProvider(id){const p=providers.find(p=>p.id===id);if(!p)return;modal={kind:'provider',id};openModal('Meet '+p.name,'Recovery specialist.',`<div class="provider-profile">${avatar(p.initial,'avatar-lg')}<h3>${p.name}</h3><p>${p.specialty}</p><div class="tag-row">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><p class="profile-about">${p.about}</p><div class="review-box"><div><span>Sample recovery quote</span><strong>${money(p.price)} USDC</strong></div><div><span>Estimated completion</span><strong>${p.eta}</strong></div><div><span>Sample accepted attempts</span><strong>${p.reliability}</strong></div><div><span>Validation focus</span><strong>${p.checks}</strong></div></div><p class="form-help">Quotes cover the leftover rows. USDC moves only after you accept the output.</p></div>`,`<button type="button" class="btn btn-outline" data-action="save-provider" data-id="${p.id}">${state.savedProviders.includes(id)?'Unsave specialist':'Save specialist'} ${icon('plus')}</button><button type="button" class="btn btn-dark" data-action="use-provider" data-id="${p.id}">Hire for a job ${icon('right')}</button>`);modal={kind:'provider',id};}
function startRecovery(id){const j=state.jobs.find(j=>j.id===id);const p=providers.find(p=>p.id===state.selectedProvider);if(!j||!p||j.status!=='Needs rescue')return;if(Math.round(p.price*105)>Math.round(j.budget*100)){toast('That quote exceeds your budget cap.');return}if(live){if(p.executable===false){toast(p.name+' is not taking jobs right now.');return}authorizeRecovery(id,p.id,j.budget,j.acceptanceVersion||1).then(()=>{toast('Patch is on it. Payment waits until you accept.');return refreshLive()}).catch(err=>toast(err.message||'Could not authorize this fixer.'));return}j.originalCompleted??=j.completed;j.provider=p.id;j.price=p.price;j.status='Recovering';j.events.push({label:'Specialist selected',detail:`${p.name} · ${money(p.price)} USDC quote`,kind:'network'},{label:'Recovery started',detail:'Only remaining units are assigned',kind:'play'});persist();rerender();runSimulation(j)}
function runSimulation(j){if(recoveryTimers.has(j.id))return;const start=j.completed;let step=0;const timer=setInterval(()=>{const current=state.jobs.find(x=>x.id===j.id);if(!current||current.status!=='Recovering'){clearInterval(timer);recoveryTimers.delete(j.id);return}step++;current.completed=Math.min(current.total,start+Math.ceil((current.total-start)*step/6));if(step>=6){current.status='Awaiting review';current.completed=current.total;current.events.push({label:'Recovery completed',detail:'Output ready for acceptance',kind:'check'},{label:'Acceptance checks passed',detail:'Schema · count · uniqueness · preservation',kind:'shield'});clearInterval(timer);recoveryTimers.delete(j.id);toast('Patch is done. Check the work.')}persist();if(location.hash.startsWith('#/app/')&&!modal)rerender();},750);recoveryTimers.set(j.id,timer)}
function acceptRecovery(id){const j=state.jobs.find(j=>j.id===id&&j.status==='Awaiting review');if(!j)return;if(live){acceptJob(id).then(()=>{toast('Accepted. USDC has not moved.');return refreshLive()}).catch(err=>toast(err.message||'Could not accept this output.'));return}j.status='Verified';j.settled=true;j.acceptedAt=new Date().toISOString();j.events.push({label:'Output accepted',detail:'Customer accepted the result',kind:'check'},{label:'Receipt created',detail:`${money(j.price*1.05)} USDC`,kind:'receipt'});persist();location.hash='#/app/receipts/'+j.id;toast('Accepted. Receipt printed.');}
function exportReceipt(id){const j=state.jobs.find(j=>j.id===id&&['Verified','Accepted','Disputed','Refunded'].includes(j.status));if(!j)return;download('relayworks-receipt-'+id+'.json',JSON.stringify({live:true,real_transaction:Boolean(j.onChain),receipt_id:j.onChain?j.paymentSignature:'recorded',job_id:j.id,title:j.title,provider:j.provider,units_completed:j.completed,provider_payment_usdc:money(j.price),platform_fee_usdc:money(j.price*.05),total_usdc:money(j.price*1.05),transaction_hash:j.onChain?j.paymentSignature:null,payout_signature:j.payoutSignature||null,accepted_at:j.acceptedAt||null},null,2));toast('Receipt exported.');}
function exportPackage(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;download('relayworks-package-'+id+'.json',JSON.stringify(j.package||{version:'0.1',title:j.title,total_units:j.total,completed_units:j.originalCompleted??Math.floor(j.total*.7)},null,2));}
function resetConfirm(){modal={kind:'reset'};openModal('Start fresh?','Replace this browser’s RelayWorks data with the original samples.',`<p style="font-size:13px;line-height:1.9">Your locally created jobs, provider saves, and workspace preferences will be replaced. Export your workspace first if you want to keep a copy.</p>`,`<button type="button" class="btn btn-outline" data-action="close-modal">Keep my workspace</button><button type="button" class="btn btn-dark" data-action="confirm-reset">Reset local data</button>`);modal={kind:'reset'};}
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();const main=document.getElementById('main');if(main){main.tabIndex=-1;main.focus();main.scrollIntoView()}return}const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action;const id=target.dataset.id;if(a==='overlay-close'&&e.target!==target)return;switch(a){case 'mobile-nav':{const nav=document.querySelector('.mobile-nav');nav.classList.toggle('open');target.setAttribute('aria-expanded',String(nav.classList.contains('open')));break}case 'console-menu':document.getElementById('sidebar').classList.toggle('mobile-open');break;case 'console-close':document.getElementById('sidebar')?.classList.remove('mobile-open');break;case 'hero-demo':heroDemo();break;case 'engine-stage':selectStep(Number(target.dataset.step));break;case 'engine-pause':relayScene?.toggle();break;case 'engine-inspect':{const expanded=relayScene?.inspect();target.setAttribute('aria-pressed',String(!!expanded));target.innerHTML=icon('grid')+'<span>'+(expanded?'Assemble':'Inspect')+'</span>';break}case 'step':selectStep(Number(target.dataset.step));break;case 'code-tab':currentCode=target.dataset.lang;{const filename=document.getElementById('integration-filename');if(filename)filename.textContent=currentCode==='python'?'recovery.py':currentCode==='typescript'?'recovery.ts':'recovery-package.json'}document.getElementById('integration-code').textContent=integrationCode[currentCode];document.querySelectorAll('[data-action="code-tab"]').forEach(b=>b.classList.toggle('active',b===target));break;case 'copy-code':copyText(integrationCode[currentCode]);break;case 'copy-ca':copyCa();break;case 'new-job':newJob();break;case 'new-next':nextNew();break;case 'new-back':if(modal?.kind==='new'){modal.step=Math.max(1,modal.step-1);modal.error='';renderJobModal()}break;case 'use-sample':if(modal?.kind==='new'){modal.text=JSON.stringify(samplePackage,null,2);modal.usedSample=true;modal.files=live?sampleChunkFiles():[];document.getElementById('package-json').value=modal.text;toast(live?'Sample package and chunk files loaded.':'Sample package loaded. Continue when ready.')}break;case 'sign-in':ensureSession().then(()=>refreshLive()).catch(err=>toast(err.message==='NO_WALLET'?'Install Phantom, then sign in.':err.message));break;case 'sign-out':signOut().then(()=>{state.needsAuth=true;state.wallet='';state.jobs=[];rerender();toast('Wallet disconnected. Sign in again when you want to continue.')});break;case 'settle-job':settleJob(id).then(job=>{toast(job.paymentSignature?'Paid '+job.paymentSignature.slice(0,18)+'…':'Payment recorded.');return refreshLive()}).catch(err=>{toast(err.message||'Payment confirmation is pending.');refreshLive();});break;case 'cancel-job':cancelJob(id).then(()=>{toast('Rescue cancelled.');return refreshLive()}).catch(err=>toast(err.message||'Could not cancel.'));break;case 'retry-job':retryJob(id).then(()=>{toast('Patch can try the leftovers again.');return refreshLive()}).catch(err=>toast(err.message||'Could not retry.'));break;case 'dispute-job':{const reason=window.prompt('What should the fixer hear?');if(!reason||!reason.trim())break;disputeJob(id,reason.trim()).then(()=>{toast('Dispute recorded. An operator sends any refund.');return refreshLive()}).catch(err=>toast(err.message||'Could not open a dispute.'));break}case 'close-modal':case 'overlay-close':closeModal();break;case 'open-job':if(!e.target.closest('a'))location.hash='#/app/jobs/'+id;break;case 'job-filter':state.jobFilter=target.dataset.filter;rerender();break;case 'select-provider':state.selectedProvider=id;rerender();break;case 'start-recovery':startRecovery(id);break;case 'accept-recovery':acceptRecovery(id);break;case 'reject-recovery':{if(live){rejectJob(id).then(()=>{toast('Rejected. The preserved rows stay put.');return refreshLive()}).catch(err=>toast(err.message||'Could not reject.'));break}const j=state.jobs.find(j=>j.id===id&&j.status==='Awaiting review');if(j){j.status='Needs rescue';j.completed=j.originalCompleted??Math.floor(j.total*.7);j.provider=null;j.price=0;j.events.push({label:'Another recovery requested',detail:'Output rejected · preserved work retained',kind:'refresh'});persist();rerender();toast('Reopened. Try a different fixer.')}break}case 'provider-profile':openProvider(id);break;case 'save-provider':if(state.savedProviders.includes(id)){state.savedProviders=state.savedProviders.filter(p=>p!==id);toast('Specialist removed from saved.')}else{state.savedProviders.push(id);toast('Specialist saved to this workspace.')}persist();if(modal?.kind==='provider')openProvider(id);else if(location.hash.startsWith('#/app/'))rerender();break;case 'use-provider':state.selectedProvider=id;closeModal();{const j=state.jobs.find(j=>j.status==='Needs rescue');if(j){location.hash='#/app/jobs/'+j.id;if(location.hash==='#/app/jobs/'+j.id)rerender()}else newJob()}break;case 'market-all':state.providerSearch='';state.providerSort='recommended';rerender();break;case 'download-sample':download('relayworks-sample-package.json',JSON.stringify(samplePackage,null,2));toast('Sample package downloaded.');break;case 'export-package':exportPackage(id);toast('Recovery package exported.');break;case 'export-receipt':exportReceipt(id);break;case 'export-result':{const j=state.jobs.find(j=>j.id===id);if(j?.live){loadOutput(id).then(output=>{download('relayworks-output-'+id+'.json',JSON.stringify(output,null,2));toast('Recovered files exported.');}).catch(err=>toast(err.message||'Could not download output.'));}else{toast('Output downloads are available for API recoveries.');}break}case 'export-workspace':download('relayworks-workspace.json',JSON.stringify({live:true,exported_at:new Date().toISOString(),...state},null,2));toast('Local workspace exported.');break;case 'reset-workspace':resetConfirm();break;case 'confirm-reset':if(live){state.workspace='My workspace';state.defaultBudget=10;state.savedProviders=[];persist();closeModal();rerender();toast('Preferences reset. Jobs stay on the API.');break}for(const t of recoveryTimers.values())clearInterval(t);recoveryTimers.clear();state=defaults();persist();closeModal();rerender();toast('Workspace restored.');break;}});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){state.jobSearch=e.target.value;document.getElementById('jobs-table').innerHTML=filteredTable(state)}else if(e.target.id==='provider-search'){state.providerSearch=e.target.value;const ps=providers.filter(p=>`${p.name} ${p.specialty} ${p.tags.join(' ')}`.toLowerCase().includes(state.providerSearch.toLowerCase()));if(state.providerSort==='price')ps.sort((a,b)=>a.price-b.price);document.getElementById('market-results').innerHTML=providerCards(ps,state)}});
document.addEventListener('change',async e=>{if(e.target.id==='package-file'&&modal?.kind==='new'){const file=e.target.files?.[0];if(!file)return;if(file.size>1000000){modal.error='Keep your package under 1 MB.';renderJobModal();return}try{const text=await file.text();if(modal?.kind!=='new')return;parsePackage(text);modal.text=text;modal.error='';modal.usedSample=false;renderJobModal();toast(live?'Package loaded. Add the chunk files too.':'Package loaded locally. No upload was made.')}catch(err){modal.error=err.message;renderJobModal()}}else if(e.target.id==='chunk-files'&&modal?.kind==='new'){modal.files=[...e.target.files];modal.usedSample=false;toast(modal.files.length?(modal.files.length+' chunk file'+(modal.files.length===1?'':'s')+' ready.'):'No chunk files selected.')}else if(e.target.id==='provider-sort'){state.providerSort=e.target.value;rerender()}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();if(!e.target.reportValidity())return;const name=document.getElementById('workspace-name').value.trim();if(!name){toast('Enter a workspace name.');return}state.workspace=name;state.defaultBudget=Number(document.getElementById('default-budget').value);persist();rerender();toast('Workspace preferences saved.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.mobile-nav.open')){document.querySelector('.mobile-nav').classList.remove('open');const toggle=document.querySelector('[data-action=mobile-nav]');toggle?.setAttribute('aria-expanded','false');toggle?.focus();return}const dialog=document.querySelector('.modal');if(dialog){if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const fs=[...dialog.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')].filter(el=>el.offsetParent!==null);if(!fs.length)return;if(e.shiftKey&&document.activeElement===fs[0]){e.preventDefault();fs.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===fs.at(-1)){e.preventDefault();fs[0].focus()}}}else if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&e.target.matches('.step-tab')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=Number(e.target.dataset.step);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;selectStep(i);document.getElementById('step-tab-'+i).focus()}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))route();else{document.querySelector('.mobile-nav')?.classList.remove('open');document.querySelector('[data-action=mobile-nav]')?.setAttribute('aria-expanded','false');if(!document.querySelector('.fun')){disposeRelayScene();root.innerHTML=landing();document.title='RelayWorks | Your AI agent quit at 70%. Patch finishes the job.';setupLanding();setTimeout(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'smooth'}),0)}}});
async function boot(){route();if(!live){for(const j of state.jobs.filter(j=>j.status==='Recovering'))runSimulation(j);return}let up=false;try{const health=await Promise.race([fetch(site.apiBase+'/health',{signal:AbortSignal.timeout(1200)}),new Promise((_,reject)=>setTimeout(()=>reject(new Error('timeout')),1500))]);const body=await health.json();up=health.ok&&body.service==='relayworks';state.settlementMode=body.settlementMode;state.cluster=body.cluster||state.cluster}catch{up=false}if(!up){state.apiUnavailable=true;state.jobs=[];if(location.hash.startsWith('#/app'))rerender();return}setInterval(()=>{if(!modal&&location.hash.startsWith('#/app')&&state.jobs.some(j=>j.status==='Recovering'||j.paymentPending||['payout_pending','refund_pending'].includes(j.receiptStatus)))refreshLive()},2000);if(location.hash.startsWith('#/app'))refreshLive()}
boot();
